import { Component } from '@angular/core';

@Component({
  selector: 'app-header',
  templateUrl: './header.component.html',
  styleUrls: ['./header.component.css'],
  standalone: false
})
export class HeaderComponent {

}
<div class="header-div">
    <div class="app-name-div">
        <h1 class="app-name">Askly</h1>
        <a routerLink="/home" routerLinkActive="active"><p class="app-tagline">"Data That Speaks"</p></a>
    </div>
    <div class="results-div">
        <a routerLink="/results" routerLinkActive="active"><h1>Results</h1></a>
    </div>
</div>
